source('diagnostics/mimic/portable_lib.R')
root<-mimic_root();path<-file.path(root,'provenance/source');files<-c(list.files('diagnostics/mimic',full.names=TRUE),list.files('code/lib',pattern='\\.R$',full.names=TRUE),'diagnostics/federated/contract.R','diagnostics/federated/model_lib.R','diagnostics/waterfall/run_waterfall.py')
