fed_json(list(specification=portable_spec(),source_md5=as.list(tools::md5sum(files)),audit=jsonlite::fromJSON(file.path(root,'aggregate/final_audit.json')),dataset='MIMIC-IV-Ext-CLIF v1.1.0 from user-supplied archive; MIMIC-IV 3.1; CLIF 2.1',limitations=c('No measured POA; all source eras; no room-air coverage; raw GCS completeness required','No original three-site discovery or primary pooled estimates changed','Portable predictor is newly trained on the original three sites; MIMIC never trained or recalibrated','No actual patient-level exchange; local aggregates still need disclosure review')),file.path(root,'provenance/manifest.json'))
